$ az network dns zone show -g rg-dns -n contoso.com
{
  "name": "contoso.com",
  "type": "Microsoft.Network/dnszones",
  "location": "global",
  "properties": {
    "maxNumberOfRecordSets": 10000,
    "maxNumberOfRecordsPerRecordSet": 20
  }
}

$ az network dns record-set a list -g rg-dns -z contoso.com
[
  {
    "name": "@",
    "type": "A",
    "ttl": 3600,
    "aRecords": [ { "ipv4Address": "52.142.18.7" } ]
  },
  {
    "name": "api",
    "type": "A",
    "ttl": 3600,
    "aRecords": [ { "ipv4Address": "52.142.18.7" } ]
  }
]

$ az network vnet show -g rg-net -n vnet-app --query "{name:name,prefixes:addressSpace.addressPrefixes}"
{
  "name": "vnet-app",
  "prefixes": [ "10.1.0.0/16" ]
}
